import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.hw3Av5Vn.js";const p=JSON.parse('{"title":"Pop","description":"","frontmatter":{},"headers":[],"relativePath":"demos/POP.md","filePath":"demos/POP.md"}'),n={name:"demos/POP.md"};function s(l,e,h,i,d,c){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="pop" tabindex="-1">Pop <a class="header-anchor" href="#pop" aria-label="Permalink to &quot;Pop&quot;">​</a></h1><p>The demo songs in the pop style. Each is described below, with the features it uses; <a href="./../DEMOS">About Demos</a> lists every demo.</p><ul><li><a href="#bless_the_rains">Soft-Rock</a>: <code>bless_the_rains.yml</code></li><li><a href="#chord_progression_generator">Progressions</a>: <code>06_chord_progression_generator.yml</code></li><li><a href="#follow_chords">Follow Chords</a>: <code>22_follow_chords.yml</code></li><li><a href="#goodnight_world">Synth-Pop</a>: <code>goodnight_world.yml</code></li><li><a href="#peanut_buttercup">Soul-Pop</a>: <code>peanut_buttercup.yml</code></li><li><a href="#phrasing">Phrasing</a>: <code>23_phrasing.yml</code></li><li><a href="#rick_rolling">Dance-Pop</a>: <code>rick_rolling.yml</code></li></ul><p><a id="bless_the_rains"></a></p><h2 id="soft-rock-bless-the-rains-yml" tabindex="-1">Soft-Rock: <code>bless_the_rains.yml</code> <a class="header-anchor" href="#soft-rock-bless-the-rains-yml" aria-label="Permalink to &quot;Soft-Rock: `bless_the_rains.yml`&quot;">​</a></h2><p>An early eighties soft-rock song in the manner of Africa (Toto), with a melody of its own. The verse is low and quiet and the chorus an anthem: the tune leaps up an octave and holds long high notes in three-part harmony over big drums, a driving bass, brass and strings. The verse is in D major on I iii vi and the chorus a whole step down, in C major, on vi IV I V, as the song changes key; a brass riff on IV iii vi opens and returns; a marimba figure, congas and a flute solo.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/bless_the_rains.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/bless_the_rains.yml</code></a> · C major · 93 BPM · 3:06 · 8 scenes · 17 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="chord_progression_generator"></a></p><h2 id="progressions-06-chord-progression-generator-yml" tabindex="-1">Progressions: <code>06_chord_progression_generator.yml</code> <a class="header-anchor" href="#progressions-06-chord-progression-generator-yml" aria-label="Permalink to &quot;Progressions: `06_chord_progression_generator.yml`&quot;">​</a></h2><p>A pop song in C major made from three patterns one bar long, an arpeggio, a bass figure and a chord pad, each written over chord I and played through a progression, a different one in every scene: Pop, Fifties, Andalusian in A minor, Pachelbel&#39;s eight chords, Pop again with the pad&#39;s chords inverted so that they move less, and Pop with the pad through a Chords generator&#39;s Voice leading.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/06_chord_progression_generator.yml" target="_blank" rel="noreferrer"><code>examples/learning/06_chord_progression_generator.yml</code></a> · C major · 96 BPM · 3:00 · 6 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">key changes</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../SCENES#scene-settings">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="follow_chords"></a></p><h2 id="follow-chords-22-follow-chords-yml" tabindex="-1">Follow Chords: <code>22_follow_chords.yml</code> <a class="header-anchor" href="#follow-chords-22-follow-chords-yml" aria-label="Permalink to &quot;Follow Chords: `22_follow_chords.yml`&quot;">​</a></h2><p>A song in A minor whose chords are written in one place, a muted track called SILENT Chords. The bass, the pad and the arpeggio each play one bar, written over chord I, through a Chords generator in Follow Progression mode that moves their notes to whatever chord that track plays. The chords are heard plainly first, then the band plays without following and sounds stuck on one chord, then the bass follows alone, then everyone. Later scenes add a tune, change the chords under the same patterns, change chord twice a bar, and follow chords that a progression makes on that track.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/22_follow_chords.yml" target="_blank" rel="noreferrer"><code>examples/learning/22_follow_chords.yml</code></a> · A minor · 96 BPM · 2:40 · 8 scenes · 8 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">follow chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="goodnight_world"></a></p><h2 id="synth-pop-goodnight-world-yml" tabindex="-1">Synth-Pop: <code>goodnight_world.yml</code> <a class="header-anchor" href="#synth-pop-goodnight-world-yml" aria-label="Permalink to &quot;Synth-Pop: `goodnight_world.yml`&quot;">​</a></h2><p>An early eighties synth-pop song in the manner of Sweet Dreams (Eurythmics), with a melody of its own. A two-bar synth riff in eighths, two synths an octave apart, over i for a bar and VI and v for half a bar each; a pre-chorus on VI V i iv and a bridge on a suspended i and a major IV.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/goodnight_world.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/goodnight_world.yml</code></a> · D minor · 126 BPM · 3:03 · 11 scenes · 10 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="peanut_buttercup"></a></p><h2 id="soul-pop-peanut-buttercup-yml" tabindex="-1">Soul-Pop: <code>peanut_buttercup.yml</code> <a class="header-anchor" href="#soul-pop-peanut-buttercup-yml" aria-label="Permalink to &quot;Soul-Pop: `peanut_buttercup.yml`&quot;">​</a></h2><p>A late sixties soul-pop song in the manner of Build Me Up Buttercup (The Foundations), with a melody of its own. It starts on its chorus, as the song does: I, a dominant chord on III, IV and V, two bars each, the voices answering each clause, then I, its seventh, IV turning minor and home; the verse goes I V bVII IV; three hits and an answer on IV, iii and ii, and held notes rising on V.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/peanut_buttercup.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/peanut_buttercup.yml</code></a> · Bb major · 134 BPM · 3:06 · 11 scenes · 11 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">ties</th><th style="text-align:center;">grooves</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../GROOVES">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table><p><a id="phrasing"></a></p><h2 id="phrasing-23-phrasing-yml" tabindex="-1">Phrasing: <code>23_phrasing.yml</code> <a class="header-anchor" href="#phrasing-23-phrasing-yml" aria-label="Permalink to &quot;Phrasing: `23_phrasing.yml`&quot;">​</a></h2><p>A slow ballad in A minor whose tune is heard as written and then through a Phrasing generator with one setting changed in each scene: a deep breath after each line, a rise and fall of loudness, choppy notes, and flowing notes on the tune written short. The last two scenes are a verse and a chorus sung with the settings together.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/learning/23_phrasing.yml" target="_blank" rel="noreferrer"><code>examples/learning/23_phrasing.yml</code></a> · A minor · 68 BPM · 3:46 · 8 scenes · 6 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">phrasing</th><th style="text-align:center;">ties</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/PHRASING">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td></tr></tbody></table><p><a id="rick_rolling"></a></p><h2 id="dance-pop-rick-rolling-yml" tabindex="-1">Dance-Pop: <code>rick_rolling.yml</code> <a class="header-anchor" href="#dance-pop-rick-rolling-yml" aria-label="Permalink to &quot;Dance-Pop: `rick_rolling.yml`&quot;">​</a></h2><p>A late eighties dance-pop song in the manner of Never Gonna Give You Up (Rick Astley), with a melody of its own. Two chords a bar: IV V iii vi under the string hook and the chorus, IV V in the verse; a drum fill opens, the band stops before each chorus, and the voice sits low.</p><p><a href="https://github.com/mpdehaan/llamatron/blob/main/examples/by_genre/pop/rick_rolling.yml" target="_blank" rel="noreferrer"><code>examples/by_genre/pop/rick_rolling.yml</code></a> · Bb major · 114 BPM · 2:59 · 13 scenes · 12 tracks</p><table tabindex="0"><thead><tr><th style="text-align:center;">chords</th><th style="text-align:center;">chains</th><th style="text-align:center;">ties</th><th style="text-align:center;">progressions</th></tr></thead><tbody><tr><td style="text-align:center;"><a href="./../PATTERNS#chords">✓</a></td><td style="text-align:center;"><a href="./../generators/CHAIN">✓</a></td><td style="text-align:center;"><a href="./../PATTERNS#ties">✓</a></td><td style="text-align:center;"><a href="./../generators/CHORDS">✓</a></td></tr></tbody></table>',38)])])}const y=t(n,[["render",s]]);export{p as __pageData,y as default};
